package com.manishrawat.realestate.servlet;
import com.manishrawat.realestate.dao.*; import com.manishrawat.realestate.model.User; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.*;
@WebServlet("/dashboard") public class DashboardServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{User u=(User)r.getSession(false).getAttribute("user");r.setAttribute("user",u);r.setAttribute("unreadCount",new NotificationDAO().unreadCount(u.getId()));if("TENANT".equals(u.getRole())){r.setAttribute("applications",new ApplicationDAO().forTenant(u.getId()).size());r.setAttribute("agreements",new AgreementDAO().list(u).size());}else if("MANAGER".equals(u.getRole())){r.setAttribute("properties",new PropertyDAO().findByManager(u.getId()).size());r.setAttribute("applications",new ApplicationDAO().forManager(u.getId()).size());r.setAttribute("agreements",new AgreementDAO().list(u).size());}else{r.setAttribute("users",new UserDAO().count());r.setAttribute("pending",new PropertyDAO().countByStatus("PENDING"));}r.getRequestDispatcher("/WEB-INF/views/dashboard.jsp").forward(r,s);}catch(Exception e){throw new ServletException("Unable to load dashboard.",e);}}}
